<?php
namespace App\Models;use Illuminate\Database\Eloquent\Concerns\HasUuids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;
final class ClaimDecision extends Model{use HasUuids;protected$fillable=['claim_id','decision','approved_amount_minor','currency','reason_code','rationale','authority_snapshot','status','proposed_by','approved_by','approved_at','kind','appeal_of_decision_id','dispute_id','reason_codes','heads','authority_check_id','referral_case_id','returned_by','return_reason','returned_at','notification_delivery_id','notification_status','notified_at'];protected function casts():array{return['authority_snapshot'=>'array','approved_at'=>'datetime','reason_codes'=>'array','heads'=>'array','returned_at'=>'datetime','notified_at'=>'datetime'];}public function appealOf():BelongsTo{return$this->belongsTo(self::class,'appeal_of_decision_id');}public function claim():BelongsTo{return$this->belongsTo(Claim::class);}}
